<script setup>
import { computed, ref, onMounted, watch } from 'vue'
import { api, queryString } from '../lib/api'
import { monthRange, today, useLoad } from '../lib/utils'
import MonthControl from '../components/MonthControl.vue'
import LoadState from '../components/LoadState.vue'
import Icon from '../components/Icon.vue'
const month = ref(today().slice(0, 7)), status = ref('PUBLISHED')
const { data, loading, error, load } = useLoad(async () => {
  const [stats, calendar, moods] = await Promise.all([api(`/diaries/statistics?${queryString({ ...monthRange(month.value), status: status.value })}`), api(`/diaries/calendar?${queryString({ year: Number(month.value.slice(0, 4)), month: Number(month.value.slice(5)), status: status.value === 'ALL' ? undefined : status.value })}`), api('/moods')])
  return { stats: stats.data, calendar: calendar.data.days, moods: moods.data }
})
const max = computed(() => Math.max(1, ...(data.value?.calendar || []).map(d => d.total)))
const moodCount = id => data.value?.stats.moodDistribution.find(m => m.moodId === id)?.count || 0
watch([month, status], load); onMounted(load)
</script>
<template><div class="page-heading"><div><span class="eyebrow">NHÌN LẠI ĐỂ HIỂU MÌNH HƠN</span><h1>Một chút nhìn lại</h1><p class="muted">Hành trình viết và những sắc thái cảm xúc của bạn.</p></div><MonthControl v-model="month" /></div><div class="stats-filter"><span>Số liệu dựa trên ngày của nhật ký</span><select v-model="status" aria-label="Trạng thái thống kê"><option value="PUBLISHED">Trang đã hoàn chỉnh</option><option value="DRAFT">Bản nháp</option><option value="ALL">Tất cả trang viết</option></select></div><LoadState :loading="loading" :error="error" @retry="load"><template v-if="data"><div class="stat-grid four"><div v-for="stat in [{ icon: 'book', value: data.stats.totalEntries, label: 'Trang viết' }, { icon: 'calendar', value: data.stats.activeDays, label: 'Ngày đã viết' }, { icon: 'image', value: data.stats.imageCount, label: 'Khoảnh khắc lưu giữ' }, { icon: 'heart', value: data.stats.averageMoodScore ?? '—', label: 'Điểm cảm xúc / 5' }]" :key="stat.label" class="stat-card"><span class="stat-icon sage"><Icon :name="stat.icon" /></span><div><span class="stat-number">{{ stat.value }}</span><span class="stat-label">{{ stat.label }}</span></div></div></div><section class="panel"><div class="section-heading"><div><h2>Nhịp viết của bạn</h2><p class="muted">Mỗi trang viết là một lần bạn lắng nghe chính mình.</p></div><span class="tag">{{ data.stats.activeDays }} ngày có nhật ký</span></div><div class="activity-chart" role="img" :aria-label="`Biểu đồ số trang viết theo ngày: ${data.stats.totalEntries} trang trên ${data.stats.activeDays} ngày`"><div v-for="day in data.calendar" :key="day.date" class="chart-column"><span class="chart-value">{{ day.total || '' }}</span><div class="chart-track"><div :style="{ height: `${day.total / max * 100}%` }" :title="`${day.date}: ${day.total} trang`" /></div><span class="chart-label">{{ Number(day.date.slice(-2)) }}</span></div></div><p v-if="!data.stats.totalEntries" class="hint chart-empty">Chưa có nhật ký trong khoảng thời gian này.</p></section><div class="stats-bottom"><section class="panel"><h2>Những sắc thái trong tháng</h2><p class="muted">Không có cảm xúc đúng hay sai.</p><div v-for="mood in [...data.moods, { id: null, name: 'Chưa chọn cảm xúc', emoji: '◌' }]" :key="mood.id || 'none'" class="mood-bar-row"><span class="mood-bar-label"><span>{{ mood.emoji }}</span>{{ mood.name }}</span><div class="mood-bar"><i :style="{ width: `${data.stats.totalEntries ? moodCount(mood.id) / data.stats.totalEntries * 100 : 0}%` }" /></div><span>{{ moodCount(mood.id) }}</span></div></section><section class="reflection-card"><span class="quote-mark">“</span><h2>Có những ngày chỉ cần<br />viết ra, là đã nhẹ lòng.</h2><p>Bạn đã dành {{ data.stats.activeDays }} ngày trong tháng để nhìn lại mình. Mỗi lần ngồi xuống viết đều đáng được trân trọng.</p><span class="eyebrow">CỨ ĐI THEO NHỊP CỦA BẠN</span></section></div></template></LoadState></template>
